{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments, which may suggest risk for immune-related adverse events (irAEs). The following are not exclusionary: vitiligo, childhood asthma that has resolved, type 1 diabetes, residual hypothyroidism that required only hormone replacement, or psoriasis that does not require systemic treatment.",
      "quote": "Ongoing or recent (within 5 years) evidence of significant autoimmune disease that required treatment with systemic immunosuppressive treatments",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Age at or above 14 years.",
      "quote": "Age at or above 14 years.",
      "thresholds": [
        {
          "test": "age",
          "op": ">=",
          "value": 14,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with other systemic immune-modulating agents within fewer than 28 days prior to the first dose of cemiplimab. Examples include therapeutic vaccines, cytokine treatments, or agents that target CTLA-4, 4-1BB, or OX-40. Prior treatment with imiquimod or other topical or intralesional immune modulators will not be exclusionary.",
      "quote": "Prior treatment with other systemic immune-modulating agents within fewer than 28 days prior to the first dose of cemiplimab.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Untreated brain metastasis(es) that may be considered active. Patients with previously treated brain metastases may participate if stable for at least 6 weeks, no new or enlarging metastases, and no immunosuppressive corticosteroids for brain mets within 28 days of first dose.",
      "quote": "Untreated brain metastasis(es) that may be considered active.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of cemiplimab. Brief courses for prophylaxis (e.g., contrast allergy) are not excluded.",
      "quote": "Immunosuppressive corticosteroid doses (>10 mg prednisone daily or equivalent) within 4 weeks prior to the first dose of cemiplimab",
      "thresholds": [
        {
          "test": "prednisone dose",
          "op": ">",
          "value": 10,
          "unit": "mg/day"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Active infection requiring therapy, including positive tests for HIV-1 or HIV-2 serum antibody, hepatitis B virus (HBV), or hepatitis C virus (HCV).",
      "quote": "Active infection requiring therapy, including positive tests for human immunodeficiency virus (HIV)-1 or HIV-2 serum antibody, hepatitis B virus (HBV), or hepatitis C virus (HCV)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of pneumonitis within the last 5 years.",
      "quote": "History of pneumonitis within the last 5 years",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any anticancer treatment other than radiation therapy (chemotherapy, targeted systemic therapy, imiquimod, photodynamic therapy), investigational or standard of care, within 30 days of initial cemiplimab or planned during study. Patients receiving bisphosphonates or denosumab allowed. Radiation therapy within ≤14 days of initial cemiplimab or planned during study is exclusionary.",
      "quote": "Any anticancer treatment other than radiation therapy (chemotherapy, targeted systemic therapy, imiquimod, photodynamic therapy), investigational or standard of care, within 30 days of the initial administration of cemiplimab",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments.",
      "quote": "History of documented allergic reactions or acute hypersensitivity reaction attributed to antibody treatments",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with allergy or hypersensitivity to cemiplimab or to any of the excipients must be excluded.",
      "quote": "Patients with allergy or hypersensitivity to cemiplimab or to any of the excipients must be excluded.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Concurrent malignancy other than BCC and/or history of malignancy other than BCC within 3 years of first planned dose, except for tumors with negligible risk (e.g., adequately treated CSCC of skin, carcinoma in situ of cervix, DCIS of breast, low-risk early stage prostate adenocarcinoma with active surveillance, or biochemical-only recurrence with PSA doubling time >12 months). Patients with hematologic malignancies are excluded.",
      "quote": "Concurrent malignancy other than BCC and/or history of malignancy other than BCC within 3 years of date of first planned dose of cemiplimab",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation.",
      "quote": "Any acute or chronic psychiatric problems that, in the opinion of the investigator, make the patient ineligible for participation",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients with a history of solid organ transplant (prior corneal transplants may be allowed after discussion with medical monitor).",
      "quote": "Patients with a history of solid organ transplant",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation due to high safety risks and/or potential to affect interpretation of results.",
      "quote": "Any medical co-morbidity, physical examination finding, or metabolic dysfunction, or clinical laboratory abnormality that, in the opinion of the investigator, renders the patient unsuitable for participation",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Inability to undergo any contrast-enhanced radiologic response assessment. Patients unable to undergo CT with iodinated contrast may be eligible if disease can be measured by MRI with gadolinium, and vice versa. For Group 2, if unable to undergo any contrast-enhanced imaging, may be eligible if disease can be assessed with digital medical photography after approval.",
      "quote": "Inability to undergo any contrast-enhanced radiologic response assessment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Breastfeeding.",
      "quote": "Breastfeeding",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Positive serum pregnancy test (a false positive, if demonstrated by serial measurements and negative ultrasound, will not be exclusionary upon approval).",
      "quote": "Positive serum pregnancy test",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Receipt of live vaccines (including attenuated) within 30 days of first study treatment.",
      "quote": "Receipt of live vaccines (including attenuated) within 30 days of first study treatment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Women of childbearing potential (WOCBP) or sexually active men who are unwilling to practice highly effective contraception prior to initial dose, during study, and for at least 6 months after last dose. Highly effective methods include stable hormonal contraception, IUD/IUS, bilateral tubal ligation, vasectomized partner, or sexual abstinence. Periodic abstinence, withdrawal, spermicides only, and LAM are not acceptable.",
      "quote": "Women of childbearing potential (WOCBP)*, or sexually active men, who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior treatment with idelalisib.",
      "quote": "Prior treatment with idelalisib",
      "thresholds": []
    }
  ]
}
